package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.persistence.ExpertQualificationProtocol.*;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.ruoyi.medical.persistence.FormalInputFixture.*;
final class ExpertQualificationServiceTest {
 ExpertFixture f;@BeforeEach void prepare()throws Exception{f=new ExpertFixture();}@AfterEach void close()throws Exception{f.close();}
 static Throwable cause(Throwable x){while(x.getCause()!=null)x=x.getCause();return x;}void code(ErrorCode code,org.junit.jupiter.api.function.Executable action){var x=cause(assertThrows(Exception.class,action));assertInstanceOf(TenantAccessException.class,x);assertEquals(code,((TenantAccessException)x).code());}
 @Test void realAuthorReadsActualOriginalAndWritesCompleteIndependentJournal()throws Exception{var r=f.author();assertEquals("AUTHOR",r.path("kind").asText());assertEquals(1,f.journals.size());assertEquals(1,f.qualifications.size());assertEquals("DRAFT",f.heads.values().iterator().next().status());assertTrue(f.f.requests.get()>0);assertEquals(1,f.operations.size());assertEquals(1,f.audits.size());assertEquals(1,f.events.size());assertTrue(f.scoreAuthorities.isEmpty());assertTrue(f.bindings.isEmpty());}
 @Test void independentApprovalHasActualCurrentPublishGrantAndReviewedFixedEvidence()throws Exception{var r=f.author();var approved=f.approve(r);assertEquals("APPROVE",approved.path("kind").asText());assertEquals("APPROVED",f.heads.values().iterator().next().status());assertEquals(2,f.journals.size());var view=f.service.read(f.f.subject,"1",r.path("qualification").path("version_id").asText());assertFalse(view.path("creates_professional_licence").asBoolean());assertFalse(view.path("proves_formal_execution").asBoolean());assertEquals(1,view.path("decisions").size());}
 @Test void authorCannotApproveOwnSubmission()throws Exception{var r=f.author();code(ErrorCode.ACCESS_DENIED,()->f.service.decide(f.f.subject,"1","expert-approve-original-key",f.decision(r,"APPROVE","1")));assertEquals("DRAFT",f.heads.values().iterator().next().status());}
 @Test void expertCannotApproveEvenIfDifferentFromSubmittingAuthor()throws Exception{var r=f.author();f.actor(f.expert);code(ErrorCode.ACCESS_DENIED,()->f.service.decide(f.f.subject,"1","expert-approve-original-key",f.decision(r,"APPROVE","1")));}
 @Test void currentPublishPermissionIsRequiredIndependentlyOfConfigure()throws Exception{var r=f.author();f.actor(id(4));f.f.grants.removeIf(g->g.subjectId().equals(id(4))&&g.action().equals("agent.publish"));code(ErrorCode.ACCESS_DENIED,()->f.service.decide(f.f.subject,"1","expert-approve-original-key",f.decision(r,"APPROVE","1")));}
 @Test void absentActualCredentialReadGrantStopsBeforeGet(){f.f.grants.removeIf(g->g.action().equals("source.read"));code(ErrorCode.ACCESS_DENIED,()->f.author());assertEquals(0,f.f.requests.get());}
 @Test void explicitRightsPurposeCannotBeSubstituted(){var request=(ObjectNode)f.authorRequest();request.put("purpose","OTHER_USE");code(ErrorCode.ACCESS_DENIED,()->f.service.author(f.f.subject,"1","expert-author-original-key",request));assertEquals(0,f.f.requests.get());}
 @Test void actualOriginalCorruptionCannotCreateQualification(){f.f.corrupt.set(true);code(ErrorCode.CONTENT_MISMATCH,()->f.author());assertTrue(f.qualifications.isEmpty());}
 @Test void revocationDuringOriginalGetCannotCreateQualification(){f.f.onGet=()->f.f.allowed.set(false);code(ErrorCode.ACCESS_DENIED,()->f.author());assertTrue(f.qualifications.isEmpty());}
 @Test void independentReviewMustConfirmScopeAndOriginals()throws Exception{var r=f.author();f.actor(id(4));var q=(ObjectNode)f.decision(r,"APPROVE","1");q.put("scope_confirmed",false);code(ErrorCode.CONTENT_MISMATCH,()->f.service.decide(f.f.subject,"1","expert-approve-original-key",q));}
 @Test void missingOrChangedReviewedEvidenceCannotApprove()throws Exception{var r=f.author();f.actor(id(4));var q=(ObjectNode)f.decision(r,"APPROVE","1");q.putArray("reviewed_evidence");code(ErrorCode.CONTENT_MISMATCH,()->f.service.decide(f.f.subject,"1","expert-approve-original-key",q));}
 @Test void originalKeyRecoversAcrossSessionAndContextWithoutNewRow()throws Exception{var request=f.authorRequest();var r=f.author();when(f.f.subject.sessionId()).thenReturn(id(909));when(f.f.admission.context()).thenReturn(new com.ruoyi.medical.identity.BusinessSessionProtocol.Context(TENANT,"2","1","1"));var replay=f.service.author(f.f.subject,"2","expert-author-original-key",request);assertEquals(r,replay);assertEquals(1,f.journals.size());}
 @Test void originalKeyRejectsChangedBody()throws Exception{f.author();var q=(ObjectNode)f.authorRequest();q.put("reason","different request");code(ErrorCode.IDEMPOTENCY_CONFLICT,()->f.service.author(f.f.subject,"1","expert-author-original-key",q));}
 @Test void originalDecisionKeyRecoversAfterStateAdvanced()throws Exception{var r=f.author();var first=f.approve(r);var second=f.service.decide(f.f.subject,"1","expert-approve-original-key",f.decision(r,"APPROVE","1"));assertEquals(first,second);assertEquals(2,f.journals.size());}
 @Test void staleRevisionCannotCreateAdditionalDecision()throws Exception{var r=f.author();f.approve(r);code(ErrorCode.REVISION_CONFLICT,()->f.service.decide(f.f.subject,"1","expert-revoke-original-key",f.decision(r,"REVOKE","1")));assertEquals(2,f.journals.size());}
 @Test void approvedQualificationCanBeRevokedWithoutRereadingWithdrawnEvidence()throws Exception{var r=f.author();f.approve(r);int gets=f.f.requests.get();f.f.grants.removeIf(g->g.action().equals("source.read"));var revoked=f.service.decide(f.f.subject,"1","expert-revoke-original-key",f.decision(r,"REVOKE","2"));assertEquals("REVOKE",revoked.path("kind").asText());assertEquals("REVOKED",f.heads.values().iterator().next().status());assertEquals(gets,f.f.requests.get());}
 @Test void rejectedQualificationCannotBeApprovedLaterWithoutNewSubmission()throws Exception{var r=f.author();f.actor(id(4));f.service.decide(f.f.subject,"1","expert-reject-original-key",f.decision(r,"REJECT","1"));code(ErrorCode.ACTION_STALE,()->f.service.decide(f.f.subject,"1","expert-approve-original-key",f.decision(r,"APPROVE","2")));}
 @Test void creatorOnlyRecoveryPreservesExactRequestAndOriginalReceipt()throws Exception{var request=f.authorRequest();var receipt=f.author();var recovered=f.service.recover(f.f.subject,"1",receipt.path("operation_id").asText());assertEquals(request,recovered.path("request"));assertEquals(receipt,recovered.path("receipt"));f.actor(id(4));code(ErrorCode.OBJECT_UNAVAILABLE,()->f.service.recover(f.f.subject,"1",receipt.path("operation_id").asText()));}
 @Test void currentReadRightsCannotBeReplacedByStoredHistoricalGrant()throws Exception{var r=f.author();f.f.grants.removeIf(g->g.action().equals("configuration.read"));code(ErrorCode.ACCESS_DENIED,()->f.service.recover(f.f.subject,"1",r.path("operation_id").asText()));}
 @Test void historicalApproverGrantRotationDoesNotRewriteHumanDecision()throws Exception{var r=f.author();f.approve(r);f.f.grants.removeIf(g->g.action().equals("agent.publish"));var view=f.service.read(f.f.subject,"1",r.path("qualification").path("version_id").asText());assertEquals("APPROVED",view.path("status").asText());}
 @Test void auditOrEventTamperingFailsTypedRecovery()throws Exception{var r=f.author();f.audits.replaceAll((k,v)->"{}");code(ErrorCode.CONTENT_MISMATCH,()->f.service.recover(f.f.subject,"1",r.path("operation_id").asText()));}
 @Test void headRevisionForgeryDoesNotBecomeApproved()throws Exception{var r=f.author();var h=f.heads.values().iterator().next();f.heads.put(h.qualificationId(),new Head(h.tenantId(),h.projectId(),h.qualificationId(),"APPROVED",java.math.BigInteger.TWO,id(999),"APPROVE",h.schemaVersion(),h.schemaManifest(),h.createdBy(),h.createdAt(),h.classification(),h.updatedAt()));code(ErrorCode.CONTENT_MISMATCH,()->f.service.read(f.f.subject,"1",r.path("qualification").path("version_id").asText()));}
}
